/* Jelajah Korea Selatan — the 126-place database behind the "Ask the guide" engine. */
/* Loaded as a classic script before js/main.js, which reads the global KOREA_DB. */
/* KOREA_DB_START */
var KOREA_DB=[
{n:'Gyeongbokgung Palace',h:'경복궁',c:'Seoul',r:'Seoul',cat:['sejarah','budaya'],fee:3000,fn:'Closed Tuesdays · free in hanbok',s:'Apr · Oct–Nov',d:'The main palace of the Joseon Dynasty, built in 1395 at the foot of Bugak Mountain, with 330 traditional buildings and Gyeonghoeru Pond. The hourly guard changing ceremony (10am–2pm) is one of the liveliest spectacles in Seoul.',t:'Free entry when wearing hanbok; closed every Tuesday.'},
{n:'Changdeokgung Palace &amp; Huwon',h:'창덕궁',c:'Seoul',r:'Seoul',cat:['sejarah','budaya'],fee:3000,fn:'Huwon Garden +₩8,000 · closed Mondays',s:'Apr–Nov',d:'The second Joseon palace, listed by UNESCO for how it blends with nature. The Huwon (Secret Garden) keeps ancient ponds and trees more than 300 years old.',t:'Book a Huwon slot as early as possible — tickets sell out fast.'},
{n:'Jongmyo Shrine',h:'종묘',c:'Seoul',r:'Seoul',cat:['sejarah'],fee:1000,fn:'Free for students? Check at the counter',s:'May',d:'The ancestral shrine of the Joseon Dynasty kings, listed by UNESCO, with the Jeongjeon hall — one of the longest wooden buildings in the world. The Jongmyo Daeje ritual in May happens once a year with full royal protocol.',t:'Some slots can only be entered together with a guided tour.'},
{n:'Deoksugung Palace',h:'덕수궁',c:'Seoul',r:'Seoul',cat:['sejarah'],fee:1000,fn:'Closed Mondays',s:'Oct–Nov',d:'The palace that became King Gojong’s residence after Joseon opened to the world — the only one mixing modern western buildings. The plane-tree-covered lane beside it is the most romantic walking route in Seoul.',t:'Deoksugung Doldam-gil road is at its most beautiful in autumn.'},
{n:'Bukchon Hanok Village',h:'북촌한옥마을',c:'Seoul',r:'Seoul',cat:['budaya'],fee:0,fn:'',s:'Year-round',d:'A 600-year-old hanok village of hilly lanes and curved traditional roofs, still lived in by residents today. The crest of Bukchon-ro 11-gil offers a panorama of hanok roofs with N Seoul Tower in the background.',t:'A real residential area — walk quietly and respect the residents.'},
{n:'Insadong',h:'인사동',c:'Seoul',r:'Seoul',cat:['budaya','makanan'],fee:0,fn:'',s:'Year-round',d:'A street of Korean traditional art and crafts — ceramic shops, hanji paper, tea and calligraphy paintings. The multi-storey tea houses in the small alleys keep a calm Joseon atmosphere.',t:'SSamziegil is a spiral craft complex that is well worth a visit.'},
{n:'Jogyesa Temple',h:'조계사',c:'Seoul',r:'Seoul',cat:['budaya'],fee:0,fn:'',s:'May',d:'The head temple of Korean Jogye Buddhism, standing in the middle of the city, framed by white pines hundreds of years old. During the Lotus Lantern Festival in May, the whole grounds fill with thousands of colourful lanterns.',t:'Free and open into the evening; templestay programmes available.'},
{n:'Gwangjang Market',h:'광장시장',c:'Seoul',r:'Seoul',cat:['makanan'],fee:0,fn:'',s:'Year-round',d:'Korea’s oldest covered market (1905) and a snack paradise: mayak gimbap, bindaetteok, yukhoe and kalguksu served stall after stall. Its indoor food alley has featured in many world food documentaries.',t:'Come before 11am to avoid the long queues.'},
{n:'Namdaemun Market',h:'남대문시장',c:'Seoul',r:'Seoul',cat:['makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'Korea’s largest traditional market, with more than 10,000 stalls trading since 1414. The kalguksu alley inside is famous for hand-made noodles served from generation to generation.',t:'The best place for cheap souvenirs and morning snacks.'},
{n:'Myeongdong',h:'명동',c:'Seoul',r:'Seoul',cat:['bandar','makanan'],fee:0,fn:'',s:'Year-round',d:'The busiest shopping and cosmetics hub in Korea, which turns into a giant street food lane after sunset. Cheese tteokbokki, bite-sized corndog and bingsu are the must-eats here.',t:'The snack lane is liveliest after 6pm.'},
{n:'Cheonggyecheon',h:'청계천',c:'Seoul',r:'Seoul',cat:['bandar','alam'],fee:0,fn:'',s:'Nov',d:'A 5.8km stream restored from a covered highway in 2005, now a rest corridor in the middle of the city. The pedestrian walk is cool and full of lights at night.',t:'The Lantern Festival in Nov–Dec is the annual highlight.'},
{n:'N Seoul Tower',h:'N서울타워',c:'Seoul',r:'Seoul',cat:['bandar'],fee:21000,fn:'Cable car ±₩15,000 round trip',s:'Year-round',d:'A tower on the summit of Namsan Hill (236m) offering a 360° panorama of Seoul — one of the most iconic spots in the capital. Thousands of love locks on the deck railing are a popular visitor tradition.',t:'Take the cable car or the Namsan shuttle bus 01A/05B.'},
{n:'Hongdae',h:'홍대',c:'Seoul',r:'Seoul',cat:['bandar'],fee:0,fn:'',s:'Year-round',d:'A street art zone around Hongik University — busking, murals, vinyl shops and the youngest nightlife in Seoul. Every Saturday, the Free Market sells handmade crafts by art students.',t:'Street dance performances start at 8pm outside the station.'},
{n:'Seongsu-dong',h:'성수동',c:'Seoul',r:'Seoul',cat:['bandar'],fee:0,fn:'',s:'Year-round',d:'Nicknamed "Brooklyn of Seoul" — old shoe factories rewoven into designer cafes, pop-up stores and studios. Seoul Forest park next door offers green space and free-roaming deer.',t:'Come in the morning for the cafes before weekends get crowded.'},
{n:'Starfield COEX Library',h:'별마당도서관',c:'Seoul',r:'Seoul',cat:['bandar','keluarga'],fee:0,fn:'',s:'Year-round',d:'A giant public library in the middle of the COEX mall with bookshelves 13 metres high — one of the most loved reading spaces in the world. Glass walls spill light into the two-storey gallery.',t:'Combine it with Bongeunsa Temple right next door.'},
{n:'Korean War Memorial',h:'전쟁기념관',c:'Seoul',r:'Seoul',cat:['sejarah','keluarga'],fee:0,fn:'',s:'Year-round',d:'The largest military museum in Asia, documenting the 1950–53 Korean War and the country’s defence history. The outdoor field displays more than 160 real aircraft, tanks and ships.',t:'Free; the outdoor exhibits are very suitable for children.'},
{n:'National Museum of Korea',h:'국립중앙박물관',c:'Seoul',r:'Seoul',cat:['sejarah','budaya'],fee:0,fn:'',s:'Year-round',d:'Korea’s largest museum with more than 420,000 artefacts — the Silla gold crowns and Goryeo celadon are the highlights. Its new building is designed to absorb traditional palace architecture.',t:'Free; allow 2–3 hours for the main galleries.'},
{n:'Han River Park',h:'한강공원',c:'Seoul',r:'Seoul',cat:['keluarga','alam'],fee:0,fn:'Picnic mat rental ±₩3,000',s:'Apr–Oct',d:'A 40km riverside park system that acts as the backyard of Seoul residents — picnics, kite flying, cycling and instant noodles from riverside ramyeon machines. The Banpo Moonlight Rainbow Fountain on Banpo Bridge lights up every night from Apr to Oct.',t:'Use the "Congcafe" app to book picnic tents.'},
{n:'Lotte World',h:'롯데월드',c:'Seoul',r:'Seoul',cat:['keluarga'],fee:55000,fn:'Cheaper online',s:'Year-round',d:'The largest indoor theme park in the world, housed inside the Lotte World Mall shopping complex, with the outdoor Magic Island featuring the Gyro Drop coaster. Ice rink, parades and laser shows run all day.',t:'Download the Magic Pass app to shorten waiting time.'},
{n:'Seoul Grand Park &amp; Zoo',h:'서울대공원',c:'Gwacheon',r:'Incheon &amp; Gyeonggi',cat:['keluarga','alam'],fee:5000,fn:'Cable car +₩4,000',s:'Apr–Oct',d:'Korea’s largest zoo and theme park complex in the Gwacheon valley, with a cable car and more than 3,000 animals. The Museum of Modern Art (MMCA) Gwacheon branch sits right next door.',t:'Combine the zoo and MMCA for a full family day.'},
{n:'COEX Aquarium',h:'코엑스아쿠아리움',c:'Seoul',r:'Seoul',cat:['keluarga'],fee:31000,fn:'',s:'Year-round',d:'An aquarium with 183 tanks and a moving glass tunnel — sharks, rays and penguins are the main stars. It sits inside the COEX complex next to the Starfield Library.',t:'The shark feeding schedule and the diver display board are the highlights.'},
{n:'DMZ (Demilitarized Zone)',h:'비무장지대',c:'Paju',r:'Incheon &amp; Gyeonggi',cat:['sejarah'],fee:80000,fn:'Tour package ±₩50,000–90,000 · passport required',s:'Apr–Jun · Sep–Oct',d:'The most heavily guarded border in the world, dividing the Korean Peninsula since 1953 — Imjingak, the Third Infiltration Tunnel, Dora Observatory and Dorasan Station reveal a Cold War story that is still ongoing. It can only be visited through licensed guided tours.',t:'Bring a real passport; book 3–7 days ahead and avoid ripped clothing or shorts.'},
{n:'Haedong Yonggungsa Temple',h:'해동용궁사',c:'Busan',r:'Busan',cat:['budaya','alam'],fee:0,fn:'',s:'Apr · Oct',d:'A rare Buddhist temple built on the sea cliffs of eastern Busan instead of in the mountains. The Gwanseum Bosal statue of compassion faces the rising sea and the flight of 108 steps is its landmark.',t:'Come before 9am — the car park and lanes fill up quickly.'},
{n:'Haeundae Beach',h:'해운대',c:'Busan',r:'Busan',cat:['bandar','alam'],fee:0,fn:'',s:'Jun–Sep',d:'Korea’s most iconic beach, a 1.5km sweep of sand visited by 8–10 million travellers every summer. The hotel towers along the shore turn into a panorama of light at night.',t:'The east end of the beach (Dongbaekseom) is calmer for sunrise.'},
{n:'Dongbaekseom Island',h:'동백섬',c:'Busan',r:'Busan',cat:['alam'],fee:0,fn:'',s:'Year-round',d:'A small pine-wooded island linked to Haeundae Beach by a boardwalk, with the APEC Conference House and the Nurimaru lighthouse. Its 30-minute path offers the best sea views in Busan.',t:'Sunrise and Gwangan Bridge views from its tip.'},
{n:'Gamcheon Culture Village',h:'감천문화마을',c:'Busan',r:'Busan',cat:['budaya','bandar'],fee:0,fn:'',s:'Year-round',d:'A hillside village settled by war refugees that is now full of murals, sculptures and colourful lanes — nicknamed "Machu Picchu of Korea". Its tiered houses form the most photographed labyrinth in Busan.',t:'Pick up the stamp map at the visitor centre; keep quiet in residential alleys.'},
{n:'Jagalchi Market',h:'자갈치시장',c:'Busan',r:'Busan',cat:['makanan'],fee:0,fn:'',s:'Year-round',d:'Korea’s largest seafood market, run generation after generation by the women of Jagalchi. Choose live fish on the lower floor and have it cooked in the upper-floor restaurants — fresh hoe (sashimi) straight from the tanks.',t:'Gentle haggling is part of the experience.'},
{n:'BIFF Square &amp; Nampo-dong',h:'비프광장',c:'Busan',r:'Busan',cat:['makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'A street from the Busan international film festival that has become a snack hub: seeded hotteok (ssiat hotteok) and dwaeji gukbap pork soup are its specialities. Handprints of filmmakers from around the world are set along the street.',t:'The long queue at the seeded hotteok moves fast — it is worth it.'},
{n:'Gwangalli Beach',h:'광안리',c:'Busan',r:'Busan',cat:['bandar'],fee:0,fn:'',s:'Jun–Sep',d:'The beach with the most dramatic view in Busan — Gwangandaegyo Bridge lights up in colour every night in front of the row of seaside cafes. Large drone shows are held every Saturday night.',t:'Choose an upper-floor cafe for the glowing bridge panorama.'},
{n:'Taejongdae',h:'태종대',c:'Busan',r:'Busan',cat:['alam'],fee:0,fn:'Danubi train ±₩4,000',s:'Apr–Nov',d:'A seaside cliff park at the end of Yeongdo Island named after King Taejong — steep cliffs, a lighthouse and Sinseon Rock, believed to be where the gods played. The clifftop path looks out over the Korea Strait.',t:'Ride the Danubi train to save walking time.'},
{n:'Songdo Cable Car',h:'송도해상케이블카',c:'Busan',r:'Busan',cat:['keluarga','bandar'],fee:15000,fn:'±₩20,000 round trip · crystal cabin extra',s:'Year-round',d:'A cable car that crosses the sea from Songdo Beach to Dongseom Island — one of the best aerial experiences in Busan. The glass-floored "crystal" cabins give an open view straight down onto the water.',t:'The boardwalk on the island at the far end is worth exploring.'},
{n:'Beomeosa Temple',h:'범어사',c:'Busan',r:'Busan',cat:['budaya'],fee:0,fn:'',s:'Apr–Nov',d:'A grand 7th-century temple at the foot of Mount Geumjeong, one of the three main temples of Busan. The tiered Iljumun gate and ancient stone courtyard give a tranquil mood far from the metropolis.',t:'Combine it with the hiking trail to the Geumjeongsan fortress.'},
{n:'SEA LIFE Busan',h:'씨라이프부산',c:'Busan',r:'Busan',cat:['keluarga'],fee:31000,fn:'',s:'Year-round',d:'A seaside aquarium on Haeundae Beach with an 80-metre glass tunnel — sharks, giant rays and Humboldt penguins are the children’s favourites. Interactive zones let you touch starfish.',t:'Check the feeding schedule on the entrance ticket board.'},
{n:'Seongsan Ilchulbong',h:'성산일출봉',c:'Jeju',r:'Jeju',cat:['alam'],fee:5000,fn:'Closed during strong winds',s:'Year-round',d:'A 182m tuff cone volcano listed by UNESCO — the "Sunrise Peak" of Jeju, reached by a 30–45 minute climb. The summit shows a giant bowl-shaped crater facing the sea.',t:'Climb before 7am to catch sunrise before the crowds arrive.'},
{n:'Hallasan Mountain',h:'한라산',c:'Jeju',r:'Jeju',cat:['alam'],fee:0,fn:'Book the trail online',s:'Apr–Jun · Sep–Oct',d:'The highest mountain in South Korea (1,947m) in the middle of the island — all of Jeju is in fact this volcano. The Baengnokdam summit crater and azalea forest make up the country’s best hiking routes.',t:'Book a Gwaneumsa trail slot early; bring a jacket — the weather changes fast.'},
{n:'Udo Island',h:'우도',c:'Jeju',r:'Jeju',cat:['alam','keluarga'],fee:5000,fn:'Ferry round trip',s:'Apr–Oct',d:'A small island shaped like a sleeping ox north-east of Jeju — 15 minutes by ferry from Seongsan. Coastal cycling routes, free-roaming cattle and peanut-flavoured snacks are its signature.',t:'Try the Udo peanut ice cream and peanut burger.'},
{n:'Manjanggul Lava Tube',h:'만장굴',c:'Jeju',r:'Jeju',cat:['alam'],fee:2000,fn:'',s:'Year-round',d:'A 7.4km-long lava tunnel — among the longest in the world and listed by UNESCO together with part of the Jeju Geopark. A giant lava column and lava stalactites form a cold geological gallery all year round.',t:'The temperature inside the cave stays around 11–13°C — bring a light jacket.'},
{n:'Cheonjiyeon Waterfall',h:'천지연폭포',c:'Jeju',r:'Jeju',cat:['alam'],fee:2000,fn:'',s:'Year-round',d:'A 22m waterfall dropping straight into a brackish pool whose name means "pond of heaven and earth". The mullet and giant prawns in the pool can be seen clearly from the stone bridge.',t:'Most beautiful after rain; the night lights stay on until 10pm.'},
{n:'Dongmun Market',h:'동문시장',c:'Jeju',r:'Jeju',cat:['makanan'],fee:0,fn:'',s:'Year-round',d:'The oldest market in Jeju, open since 1945 — seafood, black pork and island snacks sold next to dinner stalls. The black pork alley beside it has become a destination in its own right.',t:'Come at night: the public market turns into a food street.'},
{n:'Aqua Planet Jeju',h:'아쿠아플래닛제주',c:'Jeju',r:'Jeju',cat:['keluarga'],fee:33000,fn:'',s:'Year-round',d:'Korea’s largest aquarium on the north-east of the island, with a three-storey main tank holding 50,000 sea creatures. Diver shows and the open main tank are the most popular attractions.',t:'Combine it with the nearby Seongsan Ilchulbong.'},
{n:'O&#39;sulloc Tea Plantation',h:'오설록',c:'Jeju',r:'Jeju',cat:['makanan','budaya'],fee:0,fn:'',s:'Year-round',d:'Rolling green tea fields in western Jeju with the first tea museum in Korea. The curving rows of tea, rippling like green waves, are the backdrop of the most photographed cafe on the island.',t:'The green tea roll cake and latte are musts; entry is free.'},
{n:'Bulguksa Temple',h:'불국사',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah','budaya'],fee:5000,fn:'',s:'Apr–Nov',d:'The great royal temple of 8th-century Silla, listed by UNESCO — the Cheongungyo stairs and the Dabotap and Seokgatap stone pagodas are icons of Korean Buddhist architecture. Its name means "Temple of the Buddha Land".',t:'Bus 12 leaves from the temple towards Seokguram at the hilltop.'},
{n:'Seokguram Grotto',h:'석굴암',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah'],fee:4000,fn:'',s:'Year-round',d:'An 8th-century Buddhist grotto on the summit of Mount Tohamsan — the 3.5m Sakyamuni Buddha statue faces the eastern sea, designed so that sunrise light falls on its face. Listed by UNESCO together with Bulguksa.',t:'Cold mornings; sunrise from the cave doorway is the most magical moment.'},
{n:'Daereungwon Ancient Tomb Park',h:'대릉원',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah'],fee:3000,fn:'',s:'Year-round',d:'A park holding 23 royal Silla burial mounds that form green hill silhouettes in the middle of Gyeongju. The Cheonmachong tomb is open to visitors, who can see a golden horse burial.',t:'Rent a bicycle to explore the wider tomb trails.'},
{n:'Cheomseongdae Observatory',h:'첨성대',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah'],fee:0,fn:'',s:'Year-round',d:'The oldest stone observatory in East Asia (7th century), built from 365 stone blocks that represent the days of a year. This bottle-shaped structure has stood upright for 1,400 years.',t:'Donggung &amp; Wolji Pond is only a few steps away — see both.'},
{n:'Donggung &amp; Wolji Pond',h:'동궁과월지',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah'],fee:2000,fn:'',s:'Year-round',d:'A secondary Silla palace complex beside a pond used for royal banquets. After dark, the reconstructed buildings mirror in the pond water — the most photographed scene in Gyeongju.',t:'Come after sunset for the true reflection of the lights.'},
{n:'Gyeongju National Museum',h:'경주국립박물관',c:'Gyeongju',r:'Gyeongsang',cat:['sejarah','budaya'],fee:0,fn:'',s:'Year-round',d:'Home to the Silla gold crowns, Cheonmachong tomb goods and the legendary 18-tonne bronze Emille Bell. Its main building faces the ancient tomb site.',t:'Free; 1–2 hours is enough for the main galleries.'},
{n:'Hwangnidan-gil Street',h:'황리단길',c:'Gyeongju',r:'Gyeongsang',cat:['makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'Gyeongju’s trendiest street — old hanok shop-houses turned into artsy cafes, modern Korean restaurants and craft shops. Kkwabaegi donuts and ice cream are the must-eat snacks here.',t:'Liveliest on weekend afternoons; parking is difficult.'},
{n:'Jeonju Hanok Village',h:'전주한옥마을',c:'Jeonju',r:'Jeolla',cat:['budaya'],fee:0,fn:'',s:'Year-round',d:'Korea’s largest hanok village, with more than 800 traditional houses in the middle of town — the centre of Joseon culture and food. Hanbok rental, tea in a hanok house and Jeonju bibimbap are the three must-do experiences.',t:'Climb Omokdae hill for a hanok roof panorama at dusk.'},
{n:'Gyeonggijeon Shrine',h:'경기전',c:'Jeonju',r:'Jeolla',cat:['sejarah'],fee:3000,fn:'',s:'Year-round',d:'A shrine holding the portrait of Joseon founder King Taejo Yi Seong-gye — Jeonju is his ancestral hometown. Old pine courtyards and tiered gates frame a tranquil slice of history.',t:'The Jaman mural alley is right behind it.'},
{n:'Nambu Market',h:'남부시장',c:'Jeonju',r:'Jeolla',cat:['makanan'],fee:0,fn:'Night market Fri–Sat',s:'Year-round',d:'A Jeonju public market since the 1920s known as the "mothers’ market" — fresh ingredients and street food sold side by side. Its night market fills the lanes with kkwabaegi, kongnamul gukbap bean sprout soup and modern snacks.',t:'The night market is only active on Friday and Saturday nights.'},
{n:'PNB Bakery',h:'전주피에네베',c:'Jeonju',r:'Jeolla',cat:['makanan'],fee:0,fn:'',s:'Year-round',d:'Jeonju’s legendary choco pie shop and the must-buy souvenir of the city — soft bread filled with marshmallow and coated in chocolate. The long queues mark a reputation built over decades.',t:'Buy a large box as a gift; they sell out quickly in the afternoon.'},
{n:'Chinatown Incheon',h:'인천차이나타운',c:'Incheon',r:'Incheon &amp; Gyeonggi',cat:['makanan','sejarah'],fee:0,fn:'',s:'Year-round',d:'Korea’s oldest Chinatown, born when Incheon port opened in 1883 — the origin of Korean jajangmyeon. A jajangmyeon museum, the grand Chinese gate and Jayu Freedom Park shape its hilly route.',t:'Eat jajangmyeon on the street where it was born, next to Jayu Park.'},
{n:'Songdo Central Park',h:'송도센트럴파크',c:'Incheon',r:'Incheon &amp; Gyeonggi',cat:['bandar','keluarga'],fee:0,fn:'Canal boat ±₩12,000',s:'Apr–Oct',d:'A seawater park in the heart of the smart city of Songdo — canals cruised by pedal boats between modern towers. Its design takes inspiration from Central Park in New York, in Korean form.',t:'Go up the nearby G-Tower observation tower.'},
{n:'Hwaseong Fortress Suwon',h:'수원화성',c:'Suwon',r:'Incheon &amp; Gyeonggi',cat:['sejarah'],fee:2000,fn:'',s:'Apr–Nov',d:'A 5.7km Joseon fortress encircling Suwon (1796) — a UNESCO masterpiece of military architecture with four great gates and gun towers. Its construction records are kept in the UNESCO Memory of the World register.',t:'Ride the dragon train to Haenggung Palace; sunset at Hwahongmun Gate.'},
{n:'Everland',h:'에버랜드',c:'Yongin',r:'Incheon &amp; Gyeonggi',cat:['keluarga'],fee:59000,fn:'±₩39,000 when bought online',s:'Year-round',d:'Korea’s largest theme park with Safari World, the Tulip Garden and the T-Express wooden coaster, one of the steepest in the world. It changes with the seasons — tulips, carnival, Halloween and the winter Festival of Lights.',t:'Buy tickets online; use the Q-Pass app to cut down queuing.'},
{n:'Korean Folk Village',h:'한국민속촌',c:'Yongin',r:'Incheon &amp; Gyeonggi',cat:['keluarga','budaya'],fee:25000,fn:'',s:'Year-round',d:'A Joseon village rebuilt authentically — regional houses, an old market, farmer dances, traditional weddings and boat races turned into permanent shows. It sits right next to Everland.',t:'Check the show schedule at the entrance; winter brings a Festival of Lights.'},
{n:'Seoraksan National Park',h:'설악산국립공원',c:'Sokcho',r:'Gangwon',cat:['alam'],fee:9000,fn:'Cable car ±₩12,000 extra',s:'Oct (autumn foliage)',d:'The most famous national park in Korea — the granite Ulsanbawi peak, Sinheungsa Temple and the giant stone Buddha in its valley. Its autumn foliage is considered the most beautiful in the country.',t:'Take the cable car to Gwongeumseong for a panorama without the climb.'},
{n:'Nami Island',h:'남이섬',c:'Chuncheon',r:'Gangwon',cat:['alam','keluarga'],fee:16000,fn:'Includes return ferry',s:'Oct–Nov',d:'A half-moon island in the middle of Lake Cheongpyeong, famous for its metasequoia and white pine avenue — a Winter Sonata drama location. Bicycles, a mini train and swans are its family attractions.',t:'Take the early morning ferry to avoid the large tour groups.'},
{n:'Rail Bike Gangchon',h:'강촌레일바이크',c:'Chuncheon',r:'Gangwon',cat:['keluarga','alam'],fee:30000,fn:'Price is per bike (2 riders)',s:'Apr–Nov',d:'Pedal a four-wheeled rail bike along a 4.5km old rail line through LED-lit tunnels and the Bukhan river valley. The return leg is on the regular train across the same valley.',t:'Book a morning slot online; the LED tunnels are the highlight.'},
{n:'Gyeongpo Beach &amp; Lake',h:'경포',c:'Gangneung',r:'Gangwon',cat:['alam','bandar'],fee:0,fn:'',s:'Jun–Oct',d:'An east-coast Gangneung beach with Lake Gyeongpoho behind it — a mix of sea, lake and the ancient Gyeongpodae pavilion. The Anmok cafe street nearby has made this town the coffee capital of Korea.',t:'Drink coffee on Anmok Street facing the eastern sea.'},
{n:'Daegwallyeong Sheep Farm',h:'대관령양떼목장',c:'Pyeongchang',r:'Gangwon',cat:['alam','keluarga'],fee:3000,fn:'Grass for feeding ±₩1,000',s:'May–Oct',d:'A sheep farm on the Daegwallyeong highland where you feed grass directly from your hand — the sheep follow visitors across the pasture. The cool air of the plateau lasts even in summer.',t:'Bring a jacket all year round; the slope path is gentle.'},
{n:'Hahoe Village',h:'하회마을',c:'Andong',r:'Gyeongsang',cat:['budaya','sejarah'],fee:5000,fn:'',s:'Year-round',d:'A 600-year-old ancestral village of the Ryu clan, listed by UNESCO, shaped by a bend of the Nakdong River like the taegeuk symbol. Thatched-roof houses and Hahoe talchum mask dances make it a living museum of Korean culture.',t:'A traditional ferry brings you into the village; mask dance shows run on weekends.'},
{n:'Tongyeong',h:'통영',c:'Tongyeong',r:'Gyeongsang',cat:['alam','bandar'],fee:0,fn:'Luge ±₩15,000 · cable car ±₩13,000',s:'Apr–Nov',d:'An archipelago harbour nicknamed "Naples of the East" — 570 small islands, an old market, seaside luge and the Mireuksan cable car looking over the southern sea. The most visited drama and film backdrop in South Gyeongsang.',t:'Tongyeong Luge and the view from Mireuksan are the two musts.'},
{n:'Yeosu',h:'여수',c:'Yeosu',r:'Jeolla',cat:['alam','bandar','keluarga'],fee:0,fn:'Dolsan cable car ±₩13,000',s:'Apr–Nov',d:'A southern port with "the most beautiful night sea in Korea" — Odongdo Island, the Dolsan Bridge and a cable car crossing the water. The "Yeosu Night Sea" light show is a famous annual festival.',t:'Ride the Dolsan cable car after dark; do not miss Odongdo in camellia season.'},
{n:'Suncheon Bay',h:'순천만',c:'Suncheon',r:'Jeolla',cat:['alam'],fee:2000,fn:'Skylift ticket extra',s:'Oct–Nov',d:'The largest reed wetland in Korea, home to thousands of migratory birds including the black-faced spoonbill, with a 1.2km boardwalk facing the estuary. The National Garden next door adds attractions throughout the year.',t:'Ride the skylift for the bay panorama; sunset is the highlight.'},
{n:'Damyang Bamboo Forest',h:'죽녹원',c:'Damyang',r:'Jeolla',cat:['alam'],fee:2000,fn:'',s:'Year-round',d:'A cool green bamboo forest that can be walked through all year — boardwalks between the bamboo stalks make it one of the most photographed places in Jeolla. The metasequoia lane next door is famous in adverts and dramas.',t:'Try the local bamboo dishes: daetongbap (rice cooked in a bamboo tube).'},
{n:'Seongsimdang Daejeon',h:'대전성심당',c:'Daejeon',r:'Chungcheong',cat:['makanan'],fee:0,fn:'',s:'Year-round',d:'Daejeon’s legendary bakery since 1956, the reason the city is known as a "bread town" — the queue never dies down all day. Fried soboro and cream bread are its signature icons.',t:'The Daejeon Station branch is the easiest to visit while travelling by KTX.'},
{n:'Gwanghwamun Square',h:'광화문광장',c:'Seoul',r:'Seoul',cat:['bandar','sejarah'],fee:0,fn:'Water channel runs Apr–Oct',s:'Apr–Oct',d:'The grand ceremonial boulevard in front of Gyeongbokgung, redesigned in 2022 into a plaza of pine terraces, exhibition pavilions and a shallow stream you can walk through on hot days. At one end stand the statues of King Sejong and admiral Yi Sun-sin.',t:'The night lighting plus the ankle-deep water lane makes it the easiest place in central Seoul to cool off after the palaces.'},
{n:'Dongdaemun Design Plaza (DDP)',h:'동대문디자인플라자',c:'Seoul',r:'Seoul',cat:['bandar','budaya'],fee:0,fn:'Special exhibitions ±₩10,000–15,000',s:'Year-round',d:'Zaha Hadid’s curving metal landmark built onto a restored stretch of the 600-year-old city wall, home to Seoul Fashion Week shows, design exhibitions and light festivals. The outer plaza stays open around the clock.',t:'Come after 8pm for the LED rose garden and the 24-hour wholesale shopping district right next door.'},
{n:'Changgyeonggung Palace &amp; Changgyeongwon',h:'창경궁',c:'Seoul',r:'Seoul',cat:['sejarah','budaya','keluarga'],fee:1000,fn:'Included in the 4-palace combo · closed Tuesdays',s:'Apr–Nov',d:'The palace that began as a private residence for queens and concubines, joined to Changdeokgung by a shared wall. Behind it spreads Changgyeongwon, the old imperial garden that once held a zoo and greenhouse, now a park with an art hall facade and open lawns.',t:'Buy the four-palace combination ticket — it works out cheaper than two separate entries.'},
{n:'Dongmyo Shrine &amp; Antique Market',h:'동묘',c:'Seoul',r:'Seoul',cat:['sejarah','budaya'],fee:0,fn:'Street stalls busiest at weekends',s:'Year-round',d:'A Confucian shrine honouring King Sejong and his scholars, surrounded by the sprawling second-hand market that spills over the elevated subway tracks — vintage clothing, vinyl records, old coins and retro gadgets. Ritual music performances are still held here.',t:'Sunday morning is the best hunt for cheap vintage clothes and records.'},
{n:'Ikseon-dong Hanok Village',h:'익선동한옥마을',c:'Seoul',r:'Seoul',cat:['budaya','makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'A grid of narrow hanok alleys near Jongno 3-ga turned into cafés, tea rooms, craft bars and small galleries, with the curved tile ridges still intact above the doors. It feels like Bukchon, but built for sitting down and eating.',t:'Go on a weekday afternoon — the lanes are tiny and weekend café queues can pass 40 minutes.'},
{n:'Seochon',h:'서촌',c:'Seoul',r:'Seoul',cat:['budaya','makanan'],fee:0,fn:'',s:'Year-round',d:'The quiet village west of Gyeongbokgung where the king’s servants once lived, keeping painter studios, used bookshops, hanok cafés and a night alley of soju-and-anchovy bars. The lanes climb gently toward Inwangsan’s granite shoulder.',t:'Pair Seochon with Tongin Market, two minutes away, for a traditional dosirak lunch.'},
{n:'Samcheong-dong',h:'삼청동',c:'Seoul',r:'Seoul',cat:['budaya','makanan','bandar'],fee:0,fn:'',s:'Apr–Nov',d:'A hillside gallery quarter between Gyeongbokgung and Bukchon, lined with small art museums, design shops, cafés behind wooden gates and the old presidential quarter. The walking lane up to the Bukchon ridge starts here.',t:'Many galleries are free and open late, and the palace wall road next to it is best in hanbok.'},
{n:'Bongeunsa Temple',h:'봉은사',c:'Seoul',r:'Seoul',cat:['budaya','sejarah'],fee:0,fn:'Templestay program by application',s:'Year-round',d:'A 1,200-year-old temple sitting calmly beneath the Gangnam towers and the COEX mall, with a 23-metre Buddha carved straight into the hillside and a courtyard of stone pagodas older than Joseon. The contrast with the offices outside is unforgettable.',t:'Join the free morning meditation session in the main hall — visitors welcome, no booking needed.'},
{n:'Myeongdong Cathedral',h:'명동성당',c:'Seoul',r:'Seoul',cat:['budaya','sejarah'],fee:0,fn:'Silence during Mass times',s:'Year-round',d:'Korea’s first brick Gothic church, finished in 1898 in the middle of the Myeongdong shopping rush, and the site where 103 Korean martyrs were canonised together. Its twin towers have watched over every Seoul uprising since.',t:'Step inside for ten quiet minutes in the afternoon — the contrast with the crowd outside is the whole point.'},
{n:'Seoullo 7017 Skygarden',h:'서울로7017',c:'Seoul',r:'Seoul',cat:['bandar','alam'],fee:0,fn:'',s:'Apr–Nov',d:'A demolished highway overpass above Seoul Station replanted as a kilometre-long elevated garden holding more than 200 plant species in hanging pots, with viewing decks over the old rail yards. It links the station to Namdaemun and the Namsan footpaths.',t:'Walk it at dusk — the planters light from below and give free views over western Seoul.'},
{n:'Noryangjin Fisheries Market',h:'노량진수산물도매시장',c:'Seoul',r:'Seoul',cat:['makanan','bandar'],fee:0,fn:'Eating halls charge a cover and sides',s:'Year-round',d:'The night heartbeat of Seoul’s seafood, where wholesale auctions run past midnight and you pick a live king crab, squid or rockfish, then carry it upstairs to an eating hall to have it sliced, grilled or boiled in front of you.',t:'After 8pm is the sweet spot — retail prices settle and the whole hall smells of grilling garlic.'},
{n:'Tongin Market',h:'통인시장',c:'Seoul',r:'Seoul',cat:['makanan','budaya'],fee:5000,fn:'Dosirak kit ±₩5,000 · brass tickets ₩500–1,000 per dish',s:'Year-round',d:'A 1941 covered market famous for its dosirak tram: buy a lunch box and brass tickets, then pay each stall a few hundred won to fill the tray with six or seven home-cooked dishes. Neighbours still do their grocery shopping here.',t:'Take the tray instead of a sit-down meal — that is the experience, and it costs less than a café lunch.'},
{n:'Mangwon Market',h:'망원시장',c:'Seoul',r:'Seoul',cat:['makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'A neighbourhood market west of the river that locals rate the best in Seoul for standing snack counters: soft egg bread, hand-beaten rice cakes, braised pig trotters, perilla pancakes and freshly fried mandu. Almost nothing here is priced for tourists.',t:'Share everything — ₩2,000–3,000 portions add up quickly and you will want to try five stalls.'},
{n:'Itaewon',h:'이태원',c:'Seoul',r:'Seoul',cat:['makanan','bandar'],fee:0,fn:'',s:'Year-round',d:'The district around the former military garrison where Seoul’s international community settled, so Turkish kebabs sit next to African stews, Belgian beer bars next to Korean BBQ, and the side streets hold vintage clothing and club basements. The first halal mosque in Korea stands on the main road.',t:'Weekend nights are loud; weekdays are better for food and for the quiet cafés climbing toward Namsan.'},
{n:'Garosu-gil',h:'가로수길',c:'Seoul',r:'Seoul',cat:['bandar','makanan'],fee:0,fn:'',s:'Apr–Nov',d:'A tree-lined pedestrian street in Sinsa-dong built around Korean designer labels, concept stores, gallery cafés and rooftop restaurants. In early June the ginkgo canopy is the reason everyone photographs it.',t:'The parallel alleys hold the better cafés — the main strip is mostly flagship stores.'},
{n:'Apgujeong Rodeo Street',h:'압구정로데오거리',c:'Seoul',r:'Seoul',cat:['bandar','makanan'],fee:0,fn:'',s:'Year-round',d:'The car-free luxury lane of Gangnam, filled with designer boutiques, flagship beauty showrooms, patisseries and the stylists’ shops that feed K-pop wardrobes. It is the polished, window-shopping face of wealthy Seoul.',t:'One subway stop away, Seolleung-ro’s antique and design cafés are the calmer counterweight.'},
{n:'Yeonnam-dong &amp; Gyeongui Line Forest Park',h:'경의선숲길',c:'Seoul',r:'Seoul',cat:['bandar','makanan','alam'],fee:0,fn:'',s:'Apr–Nov',d:'A disused rail corridor near Hongik University converted into a seven-kilometre linear park that keeps the old tracks, signals and level crossings between wildflower beds. On either side, Yeonnam-dong and Donggyo-dong became the second-hand book, vinyl and craft-beer belt.',t:'Walk it end to end from Hongik University Station — the whole route is shaded and car-free.'},
{n:'Ihwa Mural Village',h:'이화벽화마을',c:'Seoul',r:'Seoul',cat:['budaya','alam'],fee:0,fn:'Hillside homes — keep voices low',s:'Apr–Nov',d:'A steep housing hill behind Dongdaemun that artists covered with murals, from flying fish painted across stairways to the golden rabbit at the crest. The climb pays off with a full panorama over Seoul’s rooftops and the fortress wall above.',t:'Take the bus up and walk down — the endless stairs are brutal in summer heat.'},
{n:'Naksan Park &amp; Seoul City Wall',h:'낙산공원',c:'Seoul',r:'Seoul',cat:['alam','sejarah'],fee:0,fn:'',s:'Year-round',d:'A wooded hill park on the restored Hanyangdoseong fortress wall, minutes from the Dongdaemun lights, where the stone rampart runs toward Insadong through old villages. It is the classic sunset walk over central Seoul.',t:'The west-facing wall path is the quietest place to watch the city lights switch on.'},
{n:'Bukhansan National Park',h:'북한산',c:'Seoul',r:'Seoul',cat:['alam','keluarga'],fee:0,fn:'Cable car at the visitor gate extra',s:'Apr–Nov',d:'The granite fortress mountain guarding Seoul’s north, reachable by subway in under an hour, with 1,300-metre peaks, a 7-kilometre stone rampart and a giant Buddha carved into the cliff at the Pyeonghwallam hermitage. Its Baegundae trail is the most-climbed city hike in Korea.',t:'Take the Insubi or Daeung gate for white granite walls without the Baegundae queue.'},
{n:'Seoul Forest',h:'서울숲',c:'Seoul',r:'Seoul',cat:['alam','keluarga'],fee:0,fn:'',s:'Apr–Nov',d:'A hundred-hectare former royal hunting ground reopened in 2005 as a wetland garden, a deer pasture you can walk into, a children’s animal farm and old plane-tree avenues beside the river. It is the greenest free day out on the east side of the city.',t:'Use the Daebang gate for the boardwalk marsh — far quieter than the main Seoul Forest Station entrance.'},
{n:'Olympic Park (Seoul Sports Complex)',h:'올림픽공원',c:'Seoul',r:'Seoul',cat:['sejarah','alam','keluarga'],fee:0,fn:'Concerts and museums extra',s:'Apr–Nov',d:'The park left from the 1988 Seoul Olympics, laid around Baekje-era fortress remains, a stone watchtower and hundreds of donated sculptures, with cycling lanes between the arenas where K-pop shows still sell out. The fountain plaza runs on the old broadcast lawn.',t:'The Peace Plaza fountain and the illuminated monument road are best after sunset.'},
{n:'Seoul World Cup Park',h:'서울월드컵공원',c:'Seoul',r:'Seoul',cat:['alam','keluarga'],fee:0,fn:'Eco forest has restricted hours',s:'Apr–Nov',d:'A park built on top of the landfill that buried the Nanji stream, raised into grass domes, reed marshes and a viewpoint mound beside the 2002 World Cup stadium. Kites, picnics and the Bio Dome hill are its signature sights.',t:'Climb the dome at sunset for the river skyline — the marsh boardwalks are best in early autumn.'},
{n:'Banpo Bridge Rainbow Fountain',h:'반포대교 달빛무지개분수',c:'Seoul',r:'Seoul',cat:['bandar','keluarga'],fee:0,fn:'Shows Apr–Oct, evenings only',s:'Apr–Oct',d:'The longest bridge fountain recognised by Guinness, spraying nearly 200 tonnes of river water a minute along more than a kilometre of the Han with colour and music. The best seats are the Banpo riverbank steps rather than the bridge.',t:'Watch the 20:00 show from a river cruise boat drifting underneath.'},
{n:'Seoul Sky (Lotte World Tower)',h:'서울스카이',c:'Seoul',r:'Seoul',cat:['bandar','keluarga'],fee:29000,fn:'Prices vary by time slot · Sky Deck extra',s:'Year-round',d:'The 117th-to-123rd-floor observatory of the 555-metre Lotte World Tower, Korea’s tallest building, with a glass-floored Sky Deck and a glass-walled lift that climbs in under a minute. On clear days the view reaches Incheon and the mountains beyond.',t:'Book the last slot before sunset to get daylight, dusk and night lights in one visit.'},
{n:'Seokchon Lake Park',h:'석촌호수',c:'Seoul',r:'Seoul',cat:['alam','keluarga'],fee:0,fn:'',s:'Apr–Nov',d:'A two-basin lake beside Jamsil with a 4-kilometre flat promenade under cherry trees, the Lotte Tower reflected on the water, and a floating stage. It is where southeast Seoul families cycle, walk dogs and watch the spring blossom.',t:'Rent a pedal boat with water cannons for the kids, then walk the west basin at dusk for the reflection shot.'},
{n:'Children’s Grand Park',h:'어린이대공원',c:'Seoul',r:'Seoul',cat:['keluarga','alam'],fee:0,fn:'Zoo and attractions charge separately',s:'Apr–Nov',d:'A 1973 park in Gwangjin-gu built for families, with open lawns, a circular rail ride, cherry tunnels and the small animal city inside. Entry is free, so locals treat it as a weekend picnic ground rather than a ticketed attraction.',t:'The cherry avenue here rivals Yeouido and fills far faster — come before 10am.'},
{n:'Seoul Grand Park',h:'서울대공원',c:'Seoul',r:'Seoul',cat:['keluarga','alam'],fee:5000,fn:'Zoo · garden · rail car charge separately',s:'Apr–Nov',d:'The huge complex at the Gwangju foothills holding Seoul Zoo, a rose garden, a circular mini train and the Museum of Korean Folk Life, all inside one park gate. It is the standard one-day family outing south of the river.',t:'Enter through the Seoul Zoo gate first thing, when the animals are active and the queues are empty.'},
{n:'Yeouido Hangang Park',h:'여의도한강공원',c:'Seoul',r:'Seoul',cat:['alam','keluarga','bandar'],fee:0,fn:'BBQ stands rent grills',s:'Apr–Nov',d:'The river park where Seoul goes to breathe — soft-sand beach in summer, the Yeouido cherry street in April, cycling lanes, volleyball courts and night food stalls selling ramyeon and fried chicken by the water. Fireworks festivals are held from these banks.',t:'Buy instant ramyeon from a riverside stand for a few thousand won — it is the ritual.'},
{n:'The Hyundai Seoul',h:'더현대서울',c:'Seoul',r:'Seoul',cat:['bandar','makanan'],fee:0,fn:'Outdoor Zium Terrace seasonal',s:'Year-round',d:'The department store in Yeouido that redesigned the format: an indoor wooden forest court, a floating spiral staircase, a basement food hall of pastry flagships and a roof terrace overlooking the Han. It became one of the most-photographed interiors in Seoul.',t:'Go for the basement dessert floor on a weekday — weekend waits for the famous bakeries pass an hour.'},
{n:'Seoul Botanic Park',h:'서울식물원',c:'Seoul',r:'Seoul',cat:['alam','keluarga'],fee:0,fn:'',s:'Apr–Nov',d:'A former water-treatment site on the Gimpo riverbank replanted as a public botanical garden, with a tropical glasshouse, four theme gardens and a wild meadow walk behind reed beds. Admission is free, which surprises most visitors.',t:'The tropical house is warm in winter — one of the few places in Seoul to visit in January.'},
{n:'Leeum Museum of Art',h:'리움미술관',c:'Seoul',r:'Seoul',cat:['budaya','sejarah'],fee:14000,fn:'Closed Mon · Tue · book online',s:'Year-round',d:'Samsung’s private museum in Itaewon, holding 25,000 works of Korean art alongside international contemporary pieces, in three buildings by Mario Botta, Jean Nouvel and Rem Koolhaas. The white porcelain hall alone justifies the visit.',t:'Reserve the audio guide free of charge — it turns the modern wing into something coherent.'},
{n:'National Museum of Modern &amp; Contemporary Art (MMCA)',h:'국립현대미술관',c:'Seoul',r:'Seoul',cat:['budaya'],fee:2000,fn:'Most shows free · closed Mondays',s:'Year-round',d:'Korea’s national modern art museum at Gwanghwamun, in a low concrete building around a sunken court, running the country’s biggest single-artist retrospectives and media installations. Its sister branch in Cheongju holds the permanent collection.',t:'Check the programme first — the special exhibitions are the reason to come, and some need a separate ticket.'},
{n:'National Hangeul Museum',h:'국립한글박물관',c:'Seoul',r:'Seoul',cat:['budaya','sejarah','keluarga'],fee:0,fn:'Special exhibitions ±₩3,000',s:'Year-round',d:'The museum beside the War Memorial devoted to King Sejong’s alphabet, its manuscripts, early printed books and the typewriters and keyboards that kept it alive. Interactive screens let you write your name in hangeul and print it.',t:'Air-conditioned and uncrowded — the best hour to spend in July, right after the palaces.'},
{n:'Seoul Arts Center',h:'예술의전당',c:'Seoul',r:'Seoul',cat:['budaya','keluarga'],fee:0,fn:'Performances ticketed separately',s:'Year-round',d:'South Seoul’s arts campus in Namsan-seocho, with five halls including the opera house, a calligraphy-lined outdoor colonnade, an art mall and the famous library café. The lawn concerts and exhibition halls run all year.',t:'The free outdoor arcade wall of Korean calligraphy is one of the best photo spots nobody tells you about.'},
{n:'Seodaemun Independence Park',h:'서대문독립공원',c:'Seoul',r:'Seoul',cat:['sejarah','budaya'],fee:0,fn:'Independence Hall &amp; Seodaemun Prison extra',s:'Year-round',d:'The park built around the 1908 Independence Gate, raised to honour the 1919 March First movement, next to Seodaemun Prison — a restored colonial jail you can walk through, with the cells and the courtyard kept as they were. It is Seoul’s clearest record of the occupation years.',t:'The prison hall is heavy but essential, and pairs with Seochon for lunch afterwards.'},
{n:'Yungneung &amp; Geonneung Royal Tombs',h:'융건릉',c:'Seoul',r:'Seoul',cat:['sejarah','alam'],fee:1000,fn:'Closed Mondays',s:'Apr–Nov',d:'Two royal tomb sets in one forest park in Seocho, holding King Yeongjo (the tragic father of Crown Prince Sado) and King Jeongjo, with spirit walls, stone officials and a tree-lined avenue that turns gold in November.',t:'Jeongjo’s tomb path is one of Seoul’s best autumn walks, and it is quieter than the palaces.'},
{n:'Guksadang Shaman Shrine',h:'국사당',c:'Seoul',r:'Seoul',cat:['budaya','sejarah'],fee:0,fn:'On the Namsan ridge · walk or cable car',s:'Year-round',d:'The main state shrine of Korean shamanism, perched on the Namsan ridge above the tower, where painted spirit panels, flags and offerings still draw worshippers asking for exams and luck in business.',t:'Reach it on the Namsan walking paths instead of the cable car — the trail takes 30 quiet minutes.'},
{n:'Gukje Market',h:'국제시장',c:'Busan',r:'Busan',cat:['makanan','bandar','sejarah'],fee:0,fn:'Named in the film “Ode to My Father”',s:'Year-round',d:'The market that refugee families built after the Korean War, literally named “international” because it sold UN surplus goods, and still packing dried squid, street hotdogs, hand-pulled rice cakes, textiles and counterfeit-trim fashion into covered lanes.',t:'Climb the alleys behind Nambujeon Street for the dried seafood stalls at their loudest.'},
{n:'Yongdusan Park &amp; Busan Tower',h:'용두산공원',c:'Busan',r:'Busan',cat:['bandar','sejarah'],fee:2000,fn:'Tower observatory ticket · park free',s:'Year-round',d:'A hill park in the old commercial centre reached by escalator from Gukje Market, crowned by the 120-metre Busan Tower whose deck looks over the port, the bridges and Gamcheon in the distance. The grounds hold the Ahn Jung-geun statue and the citizen-liberation monument.',t:'Ride the outdoor escalators up at night — the tower view is the reason to come back to Jung-gu.'},
{n:'Busan Modern History Museum',h:'부산근대역사관',c:'Busan',r:'Busan',cat:['sejarah','budaya'],fee:0,fn:'',s:'Year-round',d:'Housed in the 1920s trading-house façade on Gwangbok-dong, tracing Busan’s opening as a port from 1876 — the first telegraph, the first tram, the first coffee, and the wartime years, with restored embassy rooms upstairs.',t:'Free, air-conditioned and ten minutes from Gukje — an easy history primer before the war memory sites.'},
{n:'40-Step Culture Village',h:'40계문화마을',c:'Busan',r:'Busan',cat:['sejarah','budaya'],fee:0,fn:'',s:'Year-round',d:'A staircase of forty steps in Choongmu-dong where war refugees stacked shelters in 1950, rebuilt as an open-air memory lane with bronze scenes of boiling-pot kitchens, cobbled alleys and the old bus terminal. It is where modern Busan was born.',t:'Read the bronze panels first, then walk five minutes to the UN cemetery uphill.'},
{n:'Dalmaji-gil Road',h:'달맞이길',c:'Busan',r:'Busan',cat:['alam','makanan','bandar'],fee:0,fn:'',s:'Apr–Nov',d:'The “moon-gazing” lane climbing the hill above Haeundae, winding past literary monuments, art cafés, pine forests and tea houses, and finishing at a viewpoint over the beach and the sea road. Poets and students courted here for a century.',t:'Take a taxi up and walk down at sunset, stopping for hotteok halfway.'},
{n:'Songjeong Beach',h:'송정해수욕장',c:'Busan',r:'Busan',cat:['alam','keluarga'],fee:0,fn:'Surfboard rental ±₩20,000',s:'Jun–Sep',d:'A wide, quieter beach at the far end of Haeundae Bay, known for steady surf, a coastal pine walk and the old rail line that now runs the beach train. Sunsets land straight on the water here.',t:'Cheaper and calmer than Haeundae, with the S-tube bike path to Songjeong Station.'},
{n:'Songdo Beach &amp; Songido Marine Park',h:'송도해수욕장',c:'Busan',r:'Busan',cat:['alam','keluarga'],fee:0,fn:'Footbridge free · cable car separate',s:'Jun–Sep',d:'Busan’s first public beach, under white cliffs, linked by a suspension footbridge to Songido — a tiny former island now a marine park with a natural rock arch, an amphitheatre and the old lighthouse. The cable car crosses the bay above it.',t:'Cross the footbridge at dusk when the rock arch glows and the beach crowds thin out.'},
{n:'Dadaepo Beach',h:'다대포해수욕장',c:'Busan',r:'Busan',cat:['alam','keluarga'],fee:0,fn:'Seasonal ice-skating rink in winter',s:'Jun–Sep',d:'A long sandy beach at the Nakdong river mouth on the far west of Busan, with a shallow tidal flat, reed marshes and a pine belt — the standard spot to watch the sun drop into the Yellow Sea. An artificial beach pond opens beside it in summer.',t:'Come for sunset, then eat the local razor-clam porridge in the market behind the bus terminal.'},
{n:'Hwangnyeongsan Observatory',h:'황령산',c:'Busan',r:'Busan',cat:['alam','bandar'],fee:0,fn:'',s:'Year-round',d:'The 412-metre ridge between Haeundae and Suyeong with a public observatory deck that holds the widest night panorama in Busan — three bridges, two bays and the Haeundae skyline in one frame. The road up passes terraced old village lanes.',t:'Go on a clear winter night after 8pm; the sea-and-city lights are the whole reason to climb.'},
{n:'Oryukdo Skywalk',h:'오륙도스카이워크',c:'Busan',r:'Busan',cat:['alam'],fee:0,fn:'Free shoe covers required',s:'Year-round',d:'A glass viewing platform stuck 42 metres above the cliffs at Yongsan-dong, looking straight down at the six rocky islets that gave the strait its name — or five, when the tide hides the sixth. Waves explode on the rocks below.',t:'Step onto the glass when the swell is high, and combine it with the Baeyeon coastal walk north.'},
{n:'Yeongdo Coastal Road &amp; Choeseongdae',h:'영도',c:'Busan',r:'Busan',cat:['alam','sejarah','bandar'],fee:0,fn:'',s:'Year-round',d:'The island district Busan grew from, joined to the mainland by four bridges, with a cliff-side coastal road, shipyard cranes, fishing stages and Choeseongdae — a rock pavilion above the south-west headland used since the 1800s for watching the sea.',t:'Walk the fishing-port lanes before heading to Gamcheon, and photograph the crane-lined sunset at Baekyang.'},
{n:'Geumjeongsanseong Fortress',h:'금정산성',c:'Busan',r:'Busan',cat:['sejarah','alam'],fee:0,fn:'Wine-making village stalls along the wall',s:'Apr–Nov',d:'A sprawling Joseon stone fortress above Beomeosa, with 17 kilometres of wall, four gates and a village of traditional houses inside that still brews regional rice wine and sells buckwheat pancakes. The north gate ramparts are the easiest climb.',t:'Eat the handmade tofu and makguksa at the gate village — Busan’s best mountain lunch.'},
{n:'Busan Cinema Center',h:'영화의전당',c:'Busan',r:'Busan',cat:['budaya','keluarga','bandar'],fee:0,fn:'Screenings and festivals ticketed',s:'Year-round',d:'The home of the Busan International Film Festival, an enormous floating roof spanning two auditoriums over an open plaza, crossed by a 180-metre skywalk bridge. Evenings bring outdoor screenings and fountain shows on the concrete stage.',t:'Walk onto the Sky Bridge at night for the Centum City lights, free of charge.'},
{n:'Busan Museum',h:'부산박물관',c:'Busan',r:'Busan',cat:['sejarah','budaya'],fee:0,fn:'Special exhibitions ±₩3,000',s:'Year-round',d:'The city museum in Nam-gu holding the Gaya burial goods, Busan’s maritime archaeology and a folk-life yard of restored hanok, including a whale-bone house built by old coastal families.',t:'The outdoor hanok and fishing-village sets are the part children remember.'},
{n:'Busan Metropolitan Art Museum',h:'부산시립미술관',c:'Busan',r:'Busan',cat:['budaya'],fee:0,fn:'Closed Mondays',s:'Year-round',d:'A terraced concrete museum in Haeundae’s park holding Busan’s contemporary collection, large-scale media shows and the summer blockbusters that fill the queue around the reflecting pool outside.',t:'Time the visit for the evening hours in summer, when the pool and façade are lit.'},
{n:'Pyeonghwa Park',h:'평화공원',c:'Busan',r:'Busan',cat:['sejarah','alam'],fee:0,fn:'',s:'Year-round',d:'A hill park in Jung-gu that held Busan’s wartime international market and, before 1945, the city’s main shrine, now kept as a Korean War memorial with a UN commemoration plaza and monuments to the refugee years.',t:'Quiet, painful and central — visit it with the Modern History Museum and Gukje on the same afternoon.'},
{n:'Nurimaru APEC House',h:'누리마루APEC하우스',c:'Busan',r:'Busan',cat:['sejarah','budaya'],fee:0,fn:'Advance reservation required',s:'Year-round',d:'The glass pavilion on Dongbaek Island where the 2005 APEC summit was held, kept as it was on the day — the round table, the leaders’ chairs and the roof terrace over the bay.',t:'Booking ahead is the only hurdle; the deck faces the same sea the leaders photographed.'},
{n:'Seojong Beach',h:'서정해수욕장',c:'Busan',r:'Busan',cat:['alam','keluarga'],fee:0,fn:'',s:'Jun–Sep',d:'A small Gijang beach backed by a 100-year-old pine forest, with an unusually shallow flat bottom that makes it the local pick for toddlers, and the quiet coastal road of the Songdae line north.',t:'Pack a mat — there is little to buy here, and the shade of the pines is the reason to come.'},
{n:'Cheongsapo Fishing Port',h:'청사포',c:'Busan',r:'Busan',cat:['makanan','alam'],fee:0,fn:'Glass-bottom boat and capsule ride extra',s:'Year-round',d:'A working fishing village in Gijang that became Busan’s coastal postcard: a small harbour of blue boats, abalone restaurants, cafés stacked on the cliff and a glass-bottom boat that runs out to the Oryukdo rocks.',t:'Book the sea capsule or glass boat online in peak season, then eat abalone porridge in the port.'},
{n:'UN Memorial Cemetery',h:'유엔기념공원',c:'Busan',r:'Busan',cat:['sejarah'],fee:0,fn:'Free · closed flag ceremony on Sundays',s:'Year-round',d:'The only United Nations cemetery in the world, on a hill in Nam-gu, holding 2,300 Commonwealth and allied soldiers who died in the Korean War, with each nation’s flag and a rose garden maintained by the city.',t:'The 11am weekly flag ceremony, when volunteers hand out flowers at the graves, is worth timing your visit around.'}
];
